u0432\u044b\u0445 \u043f\u0440\u0438\u043c\u0435\u0440\u043e\u0432)\n- **\u0421\u043f\u043b\u0438\u0442 1: Multiple-Choice (23 \u0437\u0430\u0434\u0430\u0447\u0438)** \u2014 \u0437\u0430\u0434\u0430\u0447\u0438 \u043d\u0430 \u043b\u043e\u0433\u0438\u043a\u0443, \u043f\u043e\u043d\u0438\u043c\u0430\u043d\u0438\u0435 \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442\u0430, \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043d\u0438\u044f \u0441 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c \u043d\u0430\u0431\u043e\u0440\u043e\u043c \u0432\u0430\u0440\u0438\u0430\u043d\u0442\u043e\u0432 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, `boolean_expressions`, `formal_fallacies`, `causal_judgment`).\n- **\u0421\u043f\u043b\u0438\u0442 2: Free-Form Generation (4 \u0437\u0430\u0434\u0430\u0447\u0438)** \u2014 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u044b\u0445 \u043e\u0442\u0432\u0435\u0442\u043e\u0432 / \u0430\u043b\u0433\u043e\u0440\u0438\u0442\u043c\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043f\u043e\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438 (`dyck_languages`, `word_sorting`, `multistep_arithmetic_two`, `object_counting`).\n\n#### \u0412. \u041a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\u0440\u0443\u0435\u043c\u044b\u0435 \u0443\u0441\u043b\u043e\u0432\u0438\u044f (Controls & Fixed Variables)\n- **\u0424\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0438:** \u0434\u043b\u044f \u0438\u0441\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u044f \u0441\u0442\u043e\u0445\u0430\u0441\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u0438 \u043c\u043e\u0434\u0435\u043b\u0438 \u0438\u043d\u0444\u0435\u0440\u0435\u043d\u0441 LLM (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u043f\u043e\u0434 \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u043c 3-shot CoT) \u043f\u0440\u043e\u0432\u043e\u0434\u0438\u0442\u0441\u044f \u043e\u0434\u0438\u043d \u0440\u0430\u0437 \u0441 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c `seed` \u0438 `temperature=0`. \u041d\u0430 \u043e\u0434\u043d\u043e\u043c \u0438 \u0442\u043e\u043c \u0436\u0435 \u043f\u0443\u043b\u0435 \u0441\u0433\u0435\u043d\u0435\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u043e\u0442\u0432\u0435\u0442\u043e\u0432 \u043f\u0440\u0438\u043c\u0435\u043d\u044f\u044e\u0442\u0441\u044f \u043e\u0431\u0430 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u044f \u0432\u044b\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u043d\u0438\u044f (MinED \u0438 EM).\n- **\u042d\u043a\u0441\u0442\u0440\u0430\u043a\u0446\u0438\u044f \u043e\u0442\u0432\u0435\u0442\u043e\u0432:** \u0435\u0434\u0438\u043d\u044b\u0439 \u043f\u0430\u0440\u0441\u0435\u0440 (CoT answer trigger, \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, `Therefore, the answer is...`) \u043f\u0435\u0440\u0435\u0434 \u043f\u0435\u0440\u0435\u0434\u0430\u0447\u0435\u0439 \u0441\u0442\u0440\u043e\u043a\u0438 \u0432 \u043c\u043e\u0434\u0443\u043b\u044c \u0432\u044b\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u043d\u0438\u044f.\n- **\u041e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c (False Positives check):** \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u043e\u0441\u0442\u0438 MinED \u043a \u043b\u043e\u0436\u043d\u044b\u043c \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u044f\u043c (\u043a\u043e\u0433\u0434\u0430 \u0433\u0430\u043b\u043b\u044e\u0446\u0438\u043d\u0430\u0446\u0438\u044f \u0438\u043b\u0438 \u043d\u0435\u0432\u0435\u0440\u043d\u044b\u0439 \u043e\u0442\u0432\u0435\u0442 \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u043e \u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0431\u043b\u0438\u0437\u043a\u0438\u043c \u043f\u043e edit distance \u043a \u043f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u043e\u0439 \u043e\u043f\u0446\u0438\u0438).\n\n#### \u0413. \u041c\u0435\u0442\u0440\u0438\u043a\u0438 (Dependent Variables)\n1. **Accuracy (%):** \u0434\u043e\u043b\u044f \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u043e \u0441\u043e\u043f\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0445 \u043e\u0442\u0432\u0435\u0442\u043e\u0432:\n   - \u041e\u0431\u0449\u0430\u044f \u043f\u043e \u0432\u0441\u0435\u043c\u0443 BBH (macro-average \u043f\u043e 27 \u0437\u0430\u0434\u0430\u0447\u0430\u043c);\n   - \u041e\u0442\u0434\u0435\u043b\u044c\u043d\u043e \u043f\u043e MC (23 \u0437\u0430\u0434\u0430\u0447\u0438) \u0438 Free-form (4 \u0437\u0430\u0434\u0430\u0447\u0438).\n2. **$\\Delta \\text{Accuracy} = \\text{Acc}_{\\text{MinED}} - \\text{Acc}_{\\text{EM}}$** (\u0430\u0431\u0441\u043e\u043b\u044e\u0442\u043d\u044b\u0439 \u0438 \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u043f\u0440\u0438\u0440\u043e\u0441\u0442).\n3. **Alignment Error Rates:**\n   - *False Negatives rate (FN):* \u043c\u043e\u0434\u0435\u043b\u044c \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0430\u043b\u0430 \u0432\u0435\u0440\u043d\u043e, \u043d\u043e EM \u043d\u0435 \u0437\u0430\u0447\u0435\u043b \u0438\u0437-\u0437\u0430 \u043e\u043f\u0435\u0447\u0430\u0442\u043a\u0438/\u043b\u0438\u0448\u043d\u0435\u0433\u043e \u0441\u0438\u043c\u0432\u043e\u043b\u0430, \u0430 MinED \u0438\u0441\u043f\u0440\u0430\u0432\u0438\u043b;\n   - *False Positives rate (FP):* \u043c\u043e\u0434\u0435\u043b\u044c \u043e\u0448\u0438\u0431\u043b\u0430\u0441\u044c, \u043d\u043e MinED \u043e\u0448\u0438\u0431\u043e\u0447\u043d\u043e \u00ab\u043f\u0440\u0438\u0442\u044f\u043d\u0443\u043b\u00bb \u043e\u0442\u0432\u0435\u0442 \u043a \u0438\u0441\u0442\u0438\u043d\u043d\u043e\u0439 \u043e\u043f\u0446\u0438\u0438.\n4. **\u0421\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0437\u043d\u0430\u0447\u0438\u043c\u043e\u0441\u0442\u044c:** \u043f\u0430\u0440\u043d\u044b\u0439 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u041c\u0430\u043a-\u041d\u0435\u043c\u0430\u0440\u0430 (McNemar's test) \u043d\u0430 \u0443\u0440\u043e\u0432\u043d\u0435 \u043a\u0430\u0436\u0434\u043e\u0439 \u0437\u0430\u0434\u0430\u0447\u0438 \u0438 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0440\u0430\u043d\u0433\u043e\u0432 \u0423\u0438\u043b\u043a\u043e\u043a\u0441\u043e\u043d\u0430 \u043f\u043e 27 \u0437\u0430\u0434\u0430\u0447\u0430\u043c ($\\alpha = 0.05$).\n\n---\n\n### 3. \u041a\u043b\u044e\u0447\u0435\u0432\u044b\u0435 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f (Assumptions)\n1. **\u0421\u0445\u0435\u043c\u0430 \u0432\u044b\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u043d\u0438\u044f MinED \u043d\u0430 MC:** \u043f\u0440\u0435\u0434\u043f\u043e\u043b\u0430\u0433\u0430\u0435\u0442\u0441\u044f, \u0447\u0442\u043e \u0432 \u0437\u0430\u0434\u0430\u0447\u0430\u0445 multiple-choice MinED \u0432\u044b\u0431\u0438\u0440\u0430\u0435\u0442 \u0431\u043b\u0438\u0436\u0430\u0439\u0448\u0438\u0439 \u0432\u0430\u0440\u0438\u0430\u043d\u0442 \u0438\u0437 \u0437\u0430\u043c\u043a\u043d\u0443\u0442\u043e\u0433\u043e \u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0430 \u043a\u0430\u043d\u0434\u0438\u0434\u0430\u0442\u043e\u0432 (closed-set argmin), \u0447\u0442\u043e \u0433\u0430\u0440\u0430\u043d\u0442\u0438\u0440\u0443\u0435\u0442 \u0432\u0430\u043b\u0438\u0434\u043d\u044b\u0439 \u0432\u044b\u0431\u043e\u0440 \u043e\u043f\u0446\u0438\u0438 \u0434\u0430\u0436\u0435 \u043f\u0440\u0438 \u043d\u0435\u043f\u043e\u043b\u043d\u043e\u043c \u0441\u043e\u0432\u043f\u0430\u0434\u0435\u043d\u0438\u0438 \u0444\u043e\u0440\u043c\u0430\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f.\n2. **\u0414\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0437\u043c \u0432\u044b\u0445\u043e\u0434\u043e\u0432:** \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e, \u0447\u0442\u043e\u0431\u044b \u0440\u0430\u0437\u043d\u0438\u0446\u0430 \u0432 \u043c\u0435\u0442\u0440\u0438\u043a\u0430\u0445 \u043e\u0442\u0440\u0430\u0436\u0430\u043b\u0430 \u0438\u0441\u043a\u043b\u044e\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u043e \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u044f \u043e\u0446\u0435\u043d\u043a\u0438/\u0432\u044b\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u043d\u0438\u044f (alignment criteria), \u0430 \u043d\u0435 \u0432\u0430\u0440\u0438\u0430\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u044c \u043c\u043e\u0434\u0435\u043b\u0438.\n3. **\u0415\u0434\u0438\u043d\u044b\u0439 CoT-\u043f\u0440\u043e\u043c\u043f\u0442:** \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u0439 \u043f\u0440\u043e\u043c\u043f\u0442\u0438\u043d\u0433 BBH (Suzgun et al., 2022) \u0441 \u0446\u0435\u043f\u043e\u0447\u043a\u043e\u0439 \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043d\u0438\u0439 (CoT), \u0433\u0434\u0435 \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u044b\u0439 \u043e\u0442\u0432\u0435\u0442 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0435\u0442 \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043d\u0438\u0435.\n\n---\n\n### 4. \u041d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u0438 \u0438 \u043e\u0442\u043a\u0440\u044b\u0442\u044b\u0435 \u0432\u043e\u043f\u0440\u043e\u0441\u044b (Uncertainties / Topics)\n1. **\u0424\u043e\u0440\u043c\u0443\u043b\u0430 MinED:** \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u043b\u0438 \u043f\u043e\u0441\u0438\u043c\u0432\u043e\u043b\u044c\u043d\u043e\u0435 (character-level) \u0438\u043b\u0438 \u043f\u043e\u0442\u043e\u043a\u0435\u043d\u043d\u043e\u0435 (token-level) \u0440\u0430\u0441\u0441\u0442\u043e\u044f\u043d\u0438\u0435 \u041b\u0435\u0432\u0435\u043d\u0448\u0442\u0435\u0439\u043d\u0430? \u041f\u0440\u0438\u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u043b\u0438 \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u043d\u0430 \u0434\u043b\u0438\u043d\u0443 \u0441\u0442\u0440\u043e\u043a\u0438?\n2. **\u041f\u0440\u0430\u0432\u0438\u043b\u043e \u043f\u0440\u0438\u043c\u0435\u043d\u0435\u043d\u0438\u044f \u043a Free-Form \u0437\u0430\u0434\u0430\u0447\u0430\u043c:** \u043a\u0430\u043a \u0438\u043c\u0435\u043d\u043d\u043e MinED \u043e\u0431\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u0435\u0442 4 free-form \u0437\u0430\u0434\u0430\u0447\u0438 (\u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u043b\u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043f\u043e\u0440\u043e\u0433 \u0440\u0430\u0441\u0441\u0442\u043e\u044f\u043d\u0438\u044f, \u0438\u043b\u0438 MinED \u0442\u0430\u043c \u0441\u043e\u0432\u043f\u0430\u0434\u0430\u0435\u0442 \u0441 EM / \u043d\u0435 \u043f\u0440\u0438\u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f)?\n3. **\u0426\u0435\u043b\u0435\u0432\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c:** \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043b\u0438 \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u0430\u044f \u0431\u0430\u0437\u043e\u0432\u0430\u044f LLM (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, LLaMA-2/3, PaLM-2, GPT-3.5) \u0438\u043b\u0438 \u0430\u043d\u0430\u043b\u0438\u0437 \u043f\u0440\u043e\u0432\u043e\u0434\u0438\u0442\u0441\u044f \u043d\u0430 \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u0435 \u043c\u043e\u0434\u0435\u043b\u0435\u0439?\n\n\u0415\u0441\u043b\u0438 \u043e\u0431\u0449\u0435\u0435 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u0438 \u0441\u0442\u0440\u0443\u043a\u0442\u0443